mapper.select:
select * from report
where reporter_id = #{reporterId} and target_type = #{targetType} and target_id = #{targetId}
order by id desc limit 1

select r.*, u.name as reporterName, case r.target_type when 'BLOG' then b.title when 'ACTIVITY' then a.name end as targetTitle from report r left join user u on r.reporter_id = u.id left join blog b on r.target_type = 'BLOG' and r.target_id = b.id left join activity a on r.target_type = 'ACTIVITY' and r.target_id = a.id
r.status = #{status}
order by r.id desc

mapper.update:
update report
status = #{status}, result = #{result}, handle_time = #{handleTime}, admin_name = #{adminName},
where id = #{id}
